function [a] = alfauna(p)%ALFA	critical value for one test.%%	a = alfauna(p) determines for the p probability the critical value a %	of the standardized normal distribution for one-test.%%	Copyright (c) 2004 by Flavio Bazzana%   Department of Computer and Management Sciences%   University of Trento%   38100 - Trento ITALY%   flavio.bazzana@economia.unitn.ita = -2/sqrt(2)*erfinv(1-2*p);